BEGIN TRANSACTION;
-- Katalog Nahrendorf (2018) als SQLite-DB Rinne u. Schadler (2026)
pragma foreign_keys = of;

-- CREATE TABLES--------------------
DROP TABLE IF EXISTS "Fundorte";
CREATE TABLE "Fundorte" (
	"KatNr"	INT NOT NULL,
	"Name"	TEXT,
	"KreisID"	TEXT,
	PRIMARY KEY("KatNr"),
	CONSTRAINT "ref_FundortKreisID" FOREIGN KEY("KreisID") REFERENCES "Kreise"("KreisID")
);
DROP TABLE IF EXISTS "Gruppen";
CREATE TABLE "Gruppen" (
	"GruppeID"	TEXT NOT NULL,
	"Info"	TEXT,
	PRIMARY KEY("GruppeID")
);
DROP TABLE IF EXISTS "KatNrGruppen";
CREATE TABLE "KatNrGruppen" (
	"KatNr"	INTEGER,
	"GruppeID"	TEXT,
	CONSTRAINT "index_KatNrGruppe" UNIQUE("KatNr","GruppeID"),
	CONSTRAINT "ref_GruppenGruppeID" FOREIGN KEY("GruppeID") REFERENCES "Gruppen"("GruppeID"),
	CONSTRAINT "ref_GruppenKatNr" FOREIGN KEY("KatNr") REFERENCES "Fundorte"("KatNr")
);
DROP TABLE IF EXISTS "Katalog";
CREATE TABLE "Katalog" (
	"KatalogID"	INT,
	"KatNr"	INT,
	"Attribut"	TEXT,
	"Wert"	TEXT,
	PRIMARY KEY("KatalogID"),
	CONSTRAINT "ref_KatalogKatNr" FOREIGN KEY("KatNr") REFERENCES "Fundorte"("KatNr")
);
DROP TABLE IF EXISTS "Koord";
CREATE TABLE "Koord" (
	"KatNr"	INT,
	"wkt"	TEXT,
	"srid"	INT,
	"Quelle"	TEXT,
	CONSTRAINT "ref_KoordKatNr" FOREIGN KEY("KatNr") REFERENCES "Fundorte"("KatNr")
);
DROP TABLE IF EXISTS "Kreise";
CREATE TABLE "Kreise" (
	"KreisID"	TEXT NOT NULL,
	"Kreis"	TEXT,
	PRIMARY KEY("KreisID")
);

