 (106,22,'Fundart','Grabfund'),
 (107,22,'Befundtyp','Sieben Grabhügel, davon ein Hügel ergraben. 0,60 m unter der Hügelkuppe fand sich eine Steinpackung, darunter eine 0,20 m starke Schicht aus gelblichem Lehm. Unter dieser Schicht lag die Bestattung. Die Knochenreste lagen in einer NS-Ausdehnung von 0,65 m in dunkler Erde. Rundherum war eine große Brandschüttung aus gebranntem Lehm und Holzkohlestückchen. Unter der Brandschicht, auf der alten Oberfläche, fanden sich nördlich der Bestattung eine Steinlage und südlich der Bestattung zwei Pfostenreste mit 0,35 m und 0,25 m Dm. In der Mitte zwischen den Pfosten war die Steinlage etwas gewölbt. Nach der Entfernung der Decksteine zeigte sich eine rechteckig abgerundete Steinsetzung von 0,30 m x 0,25 m (Taf. 4,22.3). Funde:'),
 (108,22,'Fundobjekt','1. Flächenretuschierte Flügelpfeilspitze, Spitze und ein Flügel beschädigt. L.: 1,8 cm. Br.: 1,8 cm (Taf. 4,22.1)'),
