 (1368,238,'Befundtyp','B: Über dem Grab erste Aufschüttungsphase bis 0,70 m Höhe erkennbar. 7,00 m südlich des Zentrums beigabenloses Grab von 1,95 x 0,65 m Größe, N-S orientiert. 0,20 m über alter Oberfläche. Streufunde:'),
