 (1373,238,'Verbl','unbekannt'),
 (1374,239,'InvNr','AKZ 4413,32'),
 (1375,239,'Fundart','Grabfund'),
 (1376,239,'Befundtyp','Grabhügel: Dm.: 19,00 m. H.: 0,90 m. Eingetiefte Grabgrube OSO-WSW orientiert. Größe: 2,00 m x 1,55 m x 1,51 m. Am Grunde Spuren eines Leichenschattens, wohl Hocker, umgeben von einem Pfostenkranz von 4,20 m Dm. Auf Grubenboden lag eine Streitaxt (Typ A2) daneben Flintmesser. Seitlich und 0,33 m über der Axt lag ein stark beschädigter Becher. Obwohl keine Unterschiede in der Grabanfüllung bemerkt wurden, scheinen die frühe A2-Axt und der relativ späte Becher nicht zu derselben Bestattung zu gehören'),
 (1377,239,'Fundobjekt','1. Becher mit Standfuß und Fischgrätzeile unter dem Rand und über Bauch. Standfuß gekerbt. H.: 22,0 cm. Mdm.: 13,2 cm. BauchDm: 19,6 cm. Fuß: 8,2 cm (Taf. 41,239.1)'),
