 (1380,239,'Verbl','unbekannt'),
 (1381,240,'InvNr','AKZ 4413,33'),
 (1382,240,'Fundart','Grabfund'),
 (1383,240,'Befundtyp','Grabhügel: Dm.: 20,00 m. H.: 1,45 m. Keine zentrale Bestattung erkennbar. 7,00 m östlich des Zentrums flache Grabmulde, WNW-OSO orientiert. 2,20 m x 1,10 m x 0,15 m Größe, mit Holzkohleresten. Im Westen der Grube Fragment eines Bechers mit Standfuß und Fischgrätzier. 20 cm höher Scherben eines weiteren Fischgrätbechers, sowie Klingenkratzer. Dazu weitere Streuscherben und Flintgeräte'),
 (1384,240,'Fundobjekt','1. Fragmente eines Fischgrätbechers mit Standfuß (Taf. 41,240.1)'),
