 (1863,328,'Fundobjekt','Hügel 10: Dm.: 20,00 m. H.: 1,28 m. Spitzgraben von 1,00 m Breite, 0,80 m Tiefe und 14,00 m Durchmesser. Innen mit 18 Schwellbalkenspuren von 1,00;1,40 m Länge und 0,30 m Breite. Im Süden Lücke von 2,50 m, hier zwei Pfostenlöcher außerhalb des Grabens, im Norden zwei entsprechende. Zentralgrab etwas südwestlich der Hügelmitte von 1,75 m x 0,85 m x 0,8 m Größe, SW-NO orientiert, mit Leichenbrandhaufen. Etwa 2,00 m nordwestlich davon ähnliche Grube mit Baumsarg, Leichenbrand und Flintklinge. Ein drittes Grab störte den Kreisgraben im SO (Taf. 53,328.2)'),
 (1864,328,'Fundobjekt','1. Flintklinge mit Endretuschierung und Brandspuren, Längskanten mit Gebrauchsretuschierung. L.: 10,5 cm. Br.: 2,3 cm (Taf. 53,328.1)'),
