 (4757,844,'Fundobjekt','Hausgrundriß. Auf einer Fläche von ca. 25,00 m x 15,00 m wurde ein Hausgrundriß freigelegt, der aus zwei Reihen gegenüberliegender Pfostenlöcher bestand. Die beiden Schmalseiten wurden wegen der geringen Größe der untersuchten Fläche nicht mehr erfasst. Grundriss ca. 15,00 m x 5,00 m. Innerhalb des Grundrisses und auf der Restfläche wurden reiche Funde der Becherkultur gemacht. Verschiedene anschließende, schwache Verfärbungen ergaben keine Funde'),
