 (5235,902,'Lit','AFWL 3, 1985, 419 f. Nr. 416 Abb. 146,6;8'),
 (5236,903,'InvNr','MKZ 4013,70'),
 (5237,903,'Fundart','Grab- und Siedlungsfunde des Endneolithikums auf einer Emsterrasse'),
 (5238,903,'Befundtyp','A: F 01: Baumsargbestattung. Grabschacht von 2,10 x 1,60 m Größe, darin die Verfärbung eines vergangenen Baumsarges von 1,65 m x 0,60 m Größe (Taf. 148,903.A)'),
 (5239,903,'Befundtyp','16 Flintabschläge und vier retuschierte Geräte fanden sich dicht zusammenliegend. Sie waren möglicherweise in einem Behältnis aus organischem Material beigegeben. Ein Flintabschlag wurde noch separat in der Grabschachtfüllung gefunden'),
 (5240,903,'Fundobjekt','1. Allseitig kantenretuschierte Flintklinge. L.: 5,0 cm. Br.: 1,8 cm (Taf. 148,903.A1)'),
 (5241,903,'Fundobjekt','2. Schaber aus Klingenfragment. Erh. L.: 4,5 cm. Br.: 3,0 cm (Taf. 148,903.A2)'),
 (5242,903,'Fundobjekt','3. Kleiner Rundschaber. L.: 1,6 cm. Br.: 2,8 cm (Taf. 148,903.A3)'),
 (5243,903,'Fundobjekt','4. Fragment einer Flintklinge. Erh. L.: 3,4 cm. Br.: 1,8 cm (Taf. 148,903.A4)'),
 (5244,903,'Fundobjekt','5. Einseitig partiell kantenretuschierte kleine Klinge. L.: 2,6 cm. Br.: 1,3 cm (Taf. 148,903.A5)'),
 (5245,903,'Fundobjekt','6. 15 unbearbeitete Flintabschläge, die sich teilweise noch zusammenfügen lassen'),
 (5246,903,'Befundtyp','B: F 47: Grab von Kreisgraben umgeben. Der Kreisgraben wird von zwei Pfostenlöchern überschnitten. Dm.: 3,10 m. Der Grabschacht darin hatte eine Abmessung von 1,90 m x 1,20 m. Alle vier Ecken scheinen eine Pfostensetzung aufzuweisen (Taf. 149,903.B). Keine Beigaben'),
 (5247,903,'Befundtyp','C: F 9:'),
 (5248,903,'Fundobjekt','RS: ovale Eindrücke unter dem Rand und zwei Zeilen Stacheldrahtmuster (Taf. 148,903.C)'),
 (5249,903,'Befundtyp','D: F 52:'),
 (5250,903,'Fundobjekt','RS: eines Fischgrätbechers mit Innenrandverzierung, außen zwei Fischgrätzeilen, innen eine Zeile Schrägstrich (Taf. 148,903.D)'),
 (5251,903,'Befundtyp','E: F 1:'),
 (5252,903,'Fundobjekt','Zwei WS: je drei Zeilen Wickelschnur (Taf. 149,903.E)'),
 (5253,903,'Befundtyp','F: F 24:'),
 (5254,903,'Fundobjekt','1. Große Umbruchscherbe mit drei Zonen kleiner, runder Eindrücke, darunter eine Zeile Schrägstrich in Ritzlinientechnik (Taf. 149,903.F1)'),
 (5255,903,'Fundobjekt','2. WS: Stacheldrahtmuster (Taf. 149,903.F2)'),
 (5256,903,'Befundtyp','G: F 14:'),
 (5257,903,'Fundobjekt','RS: vier Rillen (Taf. 149,903.G)'),
 (5258,903,'Befundtyp','H: F 64:'),
 (5259,903,'Fundobjekt','WS: vier Rillen und Schrägstrichverzierung in Ritzlinientechnik (Taf. 149,903.H)'),
 (5260,903,'Befundtyp','I: F 94:'),
 (5261,903,'Fundobjekt','WS: vier Zeilen Wickelschnur (Taf. 149,903.I)'),
 (5262,903,'Befundtyp','J: F 15:'),
 (5263,903,'Fundobjekt','WS: zwei Zeilen Wickelschnur (Taf. 149,903.J)'),
 (5264,903,'Befundtyp','K: Nr. 272: Unterer Teil einer Grube: 1. Mehrere RS und mehrere WS eines gelbbraunen Fischgrätbechers. Mdm.: ca 17,6 cm. Die RS weisen direkt unter dem Rand eine kurze Schrägstrichverzierung auf. Die Randlippe weist eine wulstartige Verdickung auf'),
 (5265,903,'Fundobjekt','2. Mehrere unverzierte WS und Standfußfragmente, die möglicherweise zu 1. gehören. Demnach hätte der Becher wohl nur ein verziertes Oberteil gehabt (Taf. 149,903.K1; K2 )'),
 (5266,903,'Fundobjekt','Die Grube enthielt weiterhin 141 Flintabschläge, die sich teilweise noch zusammenfügen ließen. Alle Stücke stammen von einer Knolle nordischen Geschiebeflints. Alle Stücke lagen so dicht zusammen, dass man davon ausgehen kann, dass alles wie bei A. in einem Behältnis aus organischem Material beigegeben worden war. Unter den 141 Stücken befanden sich 22 Schaber unterschiedlicher Typen, drei fragliche Geräte und fünf Klingenabschläge. Ein Stück war krakeliert'),
 (5267,903,'Fundart','Gruppe 1: Schaber, die an den Längsseiten retuschiert sind'),
 (5268,903,'Fundobjekt','3. An beiden Längsseiten retuschiert, mit Rindenresten auf der Dorsalfläche. L.: 4,35 cm. Br.: 2,5 cm. St.: 0,8 cm'),
 (5269,903,'Fundobjekt','4. An einer Längsseite retuschiert. Rindenrest. Lässt sich mit dem unter 3. beschriebenen Stück zusammenfügen. L: 3,65 cm. Br.: 1,4 cm. St.: 0,85 cm'),
 (5270,903,'Fundobjekt','5. An einer Längsseite retuschiert. Ebenfalls schwache Retusche an Schmalseite. Rindenrest. L.: 3,8 cm. Br.: 2,0 cm. St.: 0,85 cm'),
 (5271,903,'Fundobjekt','6. An einer Längsseite und teilweise einer Schmalseite retuschiert. Rindenrest. L.: 3,2 cm. Br.: 2,0 cm. St.: 1,0 cm'),
 (5272,903,'Fundobjekt','7. An einer Längsseite retuschiert. Rindenrest. L.: 3,2 cm. Br.: 2,1 cm. St.: 0,6 cm'),
 (5273,903,'Fundobjekt','8. An einer Längsseite retuschiert. Mit Kalkeinschlüssen. L.: 3,35 cm. Br.: 1,8 cm. St.: 0,65 cm'),
 (5274,903,'Fundobjekt','9. An einer Längskante retuschiert. L.: 3,1 cm. Br.: 1,85 cm. St.: 0,8 cm'),
 (5275,903,'Fundobjekt','23. An einer Längskante partiell retuschiert. L.: 3,4 cm. Br.: 1,6 cm. St.: 0,5 cm'),
 (5276,903,'Fundart','Gruppe 2: Schaber, die an einer Längs- und einer Schmalseite retuschiert sind'),
 (5277,903,'Fundobjekt','10. An einer Längs- und einer Schmalseite retuschiert. L.: 2,6 cm. Br.: 2,25 cm. St.: 0,55 cm'),
 (5278,903,'Fundobjekt','11. An einer Längs- und einer Schmalseite retuschiert. Die Retusche greift auch auf die zwei Längsseiten über. Rindenrest. L.: 2,3 cm. Br.: 2,3 cm. St.: 0,4 cm (Taf. 150,903.K11)'),
 (5279,903,'Fundobjekt','12. An einer Längsseite und einer Schmalseite retuschiert. Die Retusche greift auch auf die zwei Längsseiten über. Krakeliert. L.: 2,6 cm. Br.: 2,0 cm. St.: 0,8 cm'),
 (5280,903,'Fundobjekt','13. An einer Längsseite und einer Schmalseite retuschiert. Die Retusche greift auch auf die zwei Längsseiten über. Rindenrest. L.: 2,9 cm. Br.: 2,1 cm. St.: 0,4 cm (Taf. 150,903.K13). 17. An einer Längs- und einer Schmalseite retuschiert. L.: 2,7 cm. Br.: 2,0 cm. St.: 0,5 cm'),
 (5281,903,'Fundobjekt','18. An einer Längs- und einer Schmalseite retuschiert. Die Retusche greift auch auf die zwei Schmalseiten über. L.: 2,2 cm. Br.: 1,6 cm. St.: 0,35 cm'),
 (5282,903,'Fundobjekt','19. An einer Längs- und einer Schmalseite retuschiert. L.: 2,45 cm. Br.: 2,1 cm. St.: 0,6 cm'),
 (5283,903,'Befundtyp','Gruppe 3: Schaber (Kratzer), die nur an einer Schmalseite oder einem Teil der Längsseite retuschiert sind.'),
 (5284,903,'Fundobjekt','14. An einer Schmalseite retuschiert. Auf gesamter Doralseite Rinde. L.: 2,0 cm. Br.: 1,5 cm. St.: 0,5 cm'),
 (5285,903,'Fundobjekt','15. L.: 1,6 cm. Br.: 1,7 cm. St.: 0,5 cm'),
 (5286,903,'Fundobjekt','16. An einer Schmalseite retuschiert. Rindenrest. L.: 2,4 cm. Br.: 2,1 cm. St.: 0,9 cm'),
