-- Pragma--------------------
pragma foreign_keys = on;

-- CREATE VIEWS--------------------
DROP VIEW IF EXISTS "Pfeile_Klingen_Masse";
CREATE VIEW Pfeile_Klingen_Masse as
select a.KatNr, 'Pfeilspitze' as Objekt, 
   CAST (replace(substr(a.Wert,instr(a.Wert,'Br.:')+5,5),',','.') as real) as Breite, 
   CAST (replace(substr(a.Wert,instr(a.Wert,'L.:')+4,5),',','.') as real) as Laenge, 
   a.Wert 
from Katalog as a
where a.Attribut = 'Fundobjekt' and a.Wert like '%Pfeilspi%'
union ALL
select b.KatNr, 'Klinge' as Objekt, 
  CAST (replace(substr(b.Wert,instr(b.Wert,'Br.:')+5,5),',','.') as real) as Breite, 
  CAST (replace(substr(b.Wert,instr(b.Wert,'L.:')+4,5),',','.') as real) as Laenge, 
  b.Wert 
from Katalog as b
where b.Attribut = 'Fundobjekt' and b.Wert like '%Klinge%';
DROP VIEW IF EXISTS "Pfeile_Klingen_Masse_Raum";
CREATE VIEW Pfeile_Klingen_Masse_Raum as
select c.GruppeID, c.Info, a.* from Pfeile_Klingen_Masse as a
left join KatNrGruppen as b on a.KatNr = b.KatNr
left Join Gruppen as c on b.GruppeID = c.GruppeID
where length(b.GruppeID) = 5;
COMMIT;
